pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PrivatePool} from "../src/PrivatePool.sol";

contract InvMutTest is Test {
    PrivatePool c;
    function setUp() public { c = new PrivatePool(address(this), address(this), address(this)); }
    function testFuzz_property(uint16 _feeRate) public {
        address base = address(0);
        address nft = address(0);
        try c.initialize(base, nft, 1000, 1000, 0, _feeRate, bytes32(0), false, false) {
            uint16 storedRate = c.feeRate();
            assertTrue(storedRate <= 5000);
        } catch {
            assertTrue(true);
        }
    }
}
